/* Lyric engine: per-letter sung-fill driven by window.LYRICS (generated by align.py).
 *
 * Every letter is a .lf-c span whose fill wipes ghost -> ruby from its t0 to t1 (seconds,
 * song time). Held notes have long t1 - t0, so the wipe visibly slows across the note.
 *
 *   const m = LF.mount(el, lineIndex, { mode: "flow" | "abs" })   // build spans
 *   LF.onPath(m, svgPathEl, { start: 0, align: "start" })          // optional: ride a path
 *   LF.animate(tl, m, SCENE_START, { held: "swell", settle: 0.6 }) // add tweens
 *
 * Scene timelines are local, so pass the scene's song-time start (window.SCENES[id]).
 */
(function () {
  // Palette comes from the film's CSS variables (--accent, --bone) set in index.html.
  const css = (n, d) => (getComputedStyle(document.documentElement).getPropertyValue(n).trim() || d);
  const COLORS = {
    get accent() { return css("--accent", "#E0245E"); },
    get bone() { return css("--bone", "#ECE6D8"); },
  };

  function mount(container, i, opts = {}) {
    const line = window.LYRICS[i];
    const mode = opts.mode || "flow";
    container.classList.add("lf-line", "lf-" + mode);
    container.textContent = "";
    const chars = [], words = [];
    line.words.forEach((w, wi) => {
      const wEl = document.createElement("span");
      wEl.className = "lf-w";
      w.chars.forEach((c) => {
        const cEl = document.createElement("span");
        cEl.className = "lf-c";
        cEl.textContent = c.c;
        wEl.appendChild(cEl);
        chars.push({ el: cEl, c: c.c, t0: c.t0, t1: c.t1, held: w.held, word: wi });
      });
      container.appendChild(wEl);
      words.push({ el: wEl, w: w.w, t0: w.t0, t1: w.t1, held: w.held });
      // Real span, not a text node: flex/grid containers drop whitespace-only text nodes.
      if (wi < line.words.length - 1) {
        const sp = document.createElement("span");
        sp.className = "lf-sp";
        sp.textContent = "\u00a0";
        container.appendChild(sp);
      }
    });
    return { el: container, line, chars, words };
  }

  // Scenes are built before they are laid out (rects are 0), so measure glyphs with canvas
  // using the element's computed font. Needs fonts loaded (index.html starts the loads).
  const ctx = document.createElement("canvas").getContext("2d");
  function measure(el) {
    const cs = getComputedStyle(el);
    ctx.font = `${cs.fontStyle} ${cs.fontWeight} ${cs.fontSize} ${cs.fontFamily}`;
    const ls = parseFloat(cs.letterSpacing) || 0;
    let txt = el.textContent;
    if (cs.textTransform === "uppercase") txt = txt.toUpperCase();
    else if (cs.textTransform === "lowercase") txt = txt.toLowerCase();
    return ctx.measureText(txt).width + ls * txt.length;
  }

  // Lay letters along an SVG path. The path's coordinate space must match the container's
  // pixels (e.g. an <svg viewBox="0 0 1920 1080"> filling the scene). Call after fonts load.
  function onPath(m, path, opts = {}) {
    const total = path.getTotalLength();
    const widths = m.chars.map((c) => c.el.getBoundingClientRect().width || measure(c.el));
    const space = opts.space != null ? opts.space : widths.reduce((a, b) => a + b, 0) / m.chars.length * 0.45;
    let s = opts.start || 0;
    const run = widths.reduce((a, b) => a + b, 0) + space * (m.words.length - 1);
    if (opts.align === "center") s = (total - run) / 2;
    m.el.classList.add("lf-abs");
    m.chars.forEach((c, k) => {
      if (k > 0 && c.word !== m.chars[k - 1].word) s += space;
      const mid = Math.min(total, s + widths[k] / 2);
      const p = path.getPointAtLength(mid);
      const p2 = path.getPointAtLength(Math.min(total, mid + 1));
      const ang = (Math.atan2(p2.y - p.y, p2.x - p.x) * 180) / Math.PI;
      gsap.set(c.el, { position: "absolute", left: 0, top: 0, x: p.x, y: p.y, xPercent: -50, yPercent: -50, rotation: ang });
      c.x = p.x; c.y = p.y; c.rot = ang;
      s += widths[k];
    });
    return m;
  }

  // Fill tweens. opts.held: "swell" (scale up over the hold) | "stretch" (letter-spacing) | "none".
  // opts.settle: seconds after a word ends before it cools ruby -> bone (null = stays ruby).
  function animate(tl, m, offset, opts = {}) {
    const held = opts.held || "swell";
    const settle = opts.settle === undefined ? 0.6 : opts.settle;
    const peak = opts.heldScale || 1.22;
    m.chars.forEach((c) => {
      const t0 = Math.max(0, c.t0 - offset);
      const d = Math.max(0.03, c.t1 - c.t0);
      tl.fromTo(c.el, { "--p": 0 }, { "--p": 1, duration: d, ease: "none" }, t0);
      tl.fromTo(c.el, { "--g": 0 }, { "--g": 1, duration: Math.min(0.12, d), ease: "power2.out" }, t0);
      tl.fromTo(c.el, { "--g": 1 }, { "--g": 0, duration: 0.5, ease: "power2.in", immediateRender: false }, t0 + d);
      if (c.held && held === "swell" && d > 0.25) {
        tl.fromTo(c.el, { scale: 1 }, { scale: peak, duration: d, ease: "sine.out" }, t0);
        tl.fromTo(c.el, { scale: peak }, { scale: 1, duration: 0.35, ease: "power3.inOut", immediateRender: false }, t0 + d);
      }
      if (c.held && held === "stretch" && d > 0.25) {
        tl.fromTo(c.el, { marginRight: "0em" }, { marginRight: "0.35em", duration: d, ease: "sine.out" }, t0);
      }
    });
    if (settle !== null) {
      m.words.forEach((w) => {
        const cs = m.chars.filter((c) => c.el.parentNode === w.el).map((c) => c.el);
        tl.fromTo(cs, { "--on": COLORS.accent }, { "--on": COLORS.bone, duration: 0.4, ease: "none", immediateRender: false },
          Math.max(0, w.t1 - offset + settle));
      });
    }
    return m;
  }

  // Song-time helpers for scenes (return LOCAL seconds).
  const local = (t, offset) => t - offset;
  const beats = (offset, dur, list) => (list || window.BEATS).filter((b) => b >= offset && b < offset + dur).map((b) => b - offset);
  const hits = (name, offset) => window.VOCAL_HITS[name].map((t) => t - offset);
  const word = (i, wi) => window.LYRICS[i].words[wi];

  // Scenes build inside document.fonts.ready.then(...), but by then the runtime has set inactive
  // scene slots to display:none, so every rect/offset reads 0. Run those callbacks with layout
  // forced on (display only; visibility stays hidden), then restore the runtime's exact styles.
  function withLayout(fn) {
    const forced = [];
    document.querySelectorAll("[data-composition-id]").forEach((el) => {
      for (let e = el; e && e !== document.body; e = e.parentElement) {
        if (getComputedStyle(e).display === "none") {
          forced.push([e, e.style.getPropertyValue("display"), e.style.getPropertyPriority("display")]);
          e.style.setProperty("display", "block", "important");
        }
      }
    });
    try { return fn(); } finally {
      forced.reverse().forEach(([e, v, pr]) => (v ? e.style.setProperty("display", v, pr) : e.style.removeProperty("display")));
    }
  }
  const readyDesc = Object.getOwnPropertyDescriptor(FontFaceSet.prototype, "ready");
  Object.defineProperty(document.fonts, "ready", {
    configurable: true,
    get() {
      const p = readyDesc.get.call(document.fonts);
      return { then: (ok, err) => p.then((v) => (ok ? withLayout(() => ok(v)) : v), err) };
    },
  });

  window.LF = { COLORS, mount, onPath, animate, local, beats, hits, word, measure, withLayout };
})();
